    elif n == 3:
        return str(f3)

    # Build matrix to track exponents
    # We need state: [e1, e2, e3, scum] where:
    # e1 = exp of f1, e2 = exp of f2, e3 = exp of f3
    # scum = cumulative exponent of c

    # Transition matrix for [e1(x), e2(x), e3(x), scum(x)] -> [e1(x+1), e2(x+1), e3(x+1), scum(x+1)]
    # scum(x+1) = scum(x) + 2(x+1) - 6 = scum(x) + 2x - 4

