        # exponent of f1 in fn = n - 3
        # exponent of f2 in fn = n - 2
        # exponent of f3 in fn = n - 1

        # For c exponent, we need cumsum of (2k-6) from k=4 to n
        # sum = sum_{k=4}^n (2k-6) = 2*sum(k) - 6*(n-3)
        # sum(k from 4 to n) = n(n+1)/2 - 6

        if n <= 3:
            return 0

        scum = (n * (n + 1)) // 2 - 6
        scum = 2 * scum - 6 * (n - 3)

        b1 = n - 3
        b2 = n - 2
        b3 = n - 1

        res = pow(c, scum, MOD)
        res = (res * pow(f1, b1, MOD)) % MOD
        res = (res * pow(f2, b2, MOD)) % MOD
        res = (res * pow(f3, b3, MOD)) % MOD
        return res

    return str(get_exp(n))
