        adj[u].append(v)
        adj[v].append(u)

    x = list(map(int, lines[m + 1].split()))

    total_odd = sum(x)

    # If total odd parities is odd, impossible
    if total_odd % 2 != 0:
        return '-1\n'

    # All even: empty path or cycle
    if total_odd == 0:
        return '0\n'

    # Find connected components and process each
    visited_global = [False] * (n + 1)
