    if not odd_nodes_all:
        return '0\n'

    # Simple construction: pick first odd node as start, traverse commonly to other odd
    root = odd_nodes_all[0]

    # BFS to find path
    queue = deque([(root, [root])])
    visited = {root}
    parent_path_map = {root: (None, [root])}

    while queue:
        curr, curr_path = queue.popleft()

        if curr in odd_nodes_all and len(odd_nodes_all) > 1:
