    n, r = map(int, input_str.strip().split())

    # Generate all valid integer points within distance r from origin
    valid_points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                valid_points.append((x, y))

    max_score = -1
    best_selection = None

    # Try all combinations with replacement
    for selection in combinations_with_replacement(valid_points, n):
        score = 0
        for i in range(n):
            for j in range(i+1, n):
                dx = selection[i][0] - selection[j][0]
                dy = selection[i][1] - selection[j][1]
                score += dx*dx + dy*dy

        if score > max_score:
            max_score = score
            best_selection = selection

    result = [str(max_score)]
    for x, y in best_selection:
        result.append(f"{x} {y}")

    return '\n'.join(result) + '\n'
