def solution(input_data):
    """
    Solve the Lena's Set problem.

    Args:
        input_data: String containing all input

    Returns:
        String containing output for type 3 queries
    """
    lines = input_data.strip().split("\n")
    if not lines:
        return ""

    n = int(lines[0])

    # Track active pairs by query index
    # query_index -> (x, y)
    active_pairs = {}
    has_pairs = False

    results = []

    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        t = parts[0]

        if t == 1:
            # Type 1: Add pair (a, b)
            a, b = parts[1], parts[2]
            active_pairs[i] = (a, b)
            has_pairs = True

        elif t == 2:
            # Type 2: Remove pair added at query i
            query_id = parts[1]
            if query_id in active_pairs:
                del active_pairs[query_id]
                has_pairs = False

        else:
            # Type 3: Find max(x*q + y)
            q = parts[1]

            if not has_pairs:
                results.append("EMPTY SET")
            else:
                max_val = -float('inf')
                for x, y in active_pairs.values():
                    val = x * q + y
                    if val > max_val:
                        max_val = val
                results.append(str(max_val))

    return "\n".join(results)
